CREATE OR REPLACE FUNCTION journal_entry_lines_balance_check() RETURNS trigger AS $$
DECLARE
    v_entry_id UUID;
    v_diff NUMERIC;
BEGIN
    v_entry_id := COALESCE(NEW.journal_entry_id, OLD.journal_entry_id);

    SELECT COALESCE(SUM(debit_amount), 0) - COALESCE(SUM(credit_amount), 0)
    INTO v_diff
    FROM journal_entry_lines
    WHERE journal_entry_id = v_entry_id;

    IF v_diff <> 0 THEN
        RAISE EXCEPTION 'Journal entry % is not balanced (debit/credit difference = %)', v_entry_id, v_diff
            USING ERRCODE = '23514';
    END IF;

    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

CREATE CONSTRAINT TRIGGER trg_journal_entry_lines_balance
    AFTER INSERT OR UPDATE OR DELETE ON journal_entry_lines
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION journal_entry_lines_balance_check();
